    let config = if let Some(config) = Self::config() {
      config
    } else {
      Config::new()?
    };

    let search = Search::search(&config)?;

    let compilation = Compiler::compile(&config, loader, &search.justfile)?;

    Ok(Completer {
      config,
      current,
      justfile: compilation.justfile,
    })
  }
