  /// Parse a recipe parameter
  fn parse_parameter(
    &mut self,
    arg_attributes: &mut BTreeMap<String, ArgAttribute<'src>>,
    kind: ParameterKind,
  ) -> CompileResult<'src, Parameter<'src>> {
    let export = self.accepted(Dollar)?;

    let name = self.parse_name()?;

    let default = if self.accepted(Equals)? {
      Some(self.parse_value()?)
    } else {
      None
    };

    let mut help = None;
    let mut long = None;
    let mut pattern = None;
    let mut short = None;
    let mut value = None;

    if let Some(arg) = arg_attributes.remove(name.lexeme()) {
      help = arg.help;
      long = arg.long;
      pattern = arg.pattern;
      short = arg.short;
      value = arg.value;
    }

    if kind.is_variadic() && (long.is_some() || short.is_some()) {
      return Err(name.error(CompileErrorKind::VariadicParameterWithOption));
    }

    Ok(Parameter {
      default,
      export,
      help,
      kind,
      long,
      name,
      number: self.numerator.next(),
      pattern,
      short,
      value,
    })
